            INNER JOIN TCMP.CS_PLRUN PL ON P.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
            WHERE P.TENANTID = :v_idtenant AND P.PERIODSEQ = :i_PeriodSeq
