		TBL_OFICINAS_MES = SELECT DISTINCT PAD.TENANTID, PAD.PERIODSEQ, PAD.POSITIONSEQ, PAD.PARTICIPANTSEQ, PAD.PARTICIPANTID, PAD.USERID, PAD.PREFIX, PAD.FIRSTNAME, PAD.MIDDLENAME, 
