						CASE --PRIMA COMISIONABLE
							WHEN (BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
