								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-SER%' )
							THEN BAL_S4_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
