								OR BAL_S4_POL.SALESTRANSACTIONSEQ='101')
							THEN BAL_S4_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas'
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%'
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-AgentesZona-Porcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-SER%' 
								OR BAL_S4_POL.SALESTRANSACTIONSEQ IN ('102','106','107','109','123','124','125','126','127','150','153')
								OR BAL_S4_POL.NAME LIKE 'CARTERA_LP' 
								OR BAL_S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')
							THEN BAL_S4_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (BAL_S4_POL.NAME LIKE 'DC-O-COM-INC-Agente-Campania')
							THEN BAL_S4_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos')
							THEN BAL_S4_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (BAL_S4_POL.NAME LIKE '%Recuperadas' 
									AND (LEFT(RIGHT(BAL_S4_POL.PRODUCTID,5),3) NOT IN ('501')
										OR BAL_S4_POL.ID_TIPO_AGENTE = 39)
									)
							THEN 0
							ELSE BAL_S4_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						BAL_S4_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN BAL_S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN BAL_S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN BAL_S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE BAL_S4_POL.EVENTO		
							END AS TIPO_RECIBO, 
						BAL_S4_POL.NIF, --GENERICATTRIBUTE12
						BAL_S4_POL.FEC_VTO_REC, --GENERICDATE2
						BAL_S4_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						BAL_S4_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						BAL_S4_POL.SUPERRAPEL, --GENERICBOOLEAN1
						BAL_S4_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1,
						CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS, 
						F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION --20250508 LLS
					
					FROM EXT.OUT_BAL_S4_POLIZAS_REP BAL_S4_POL
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = BAL_S4_POL.PERIODSEQ
					LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = BAL_S4_POL.PERIODSEQ
						AND B.PAYEESEQ = BAL_S4_POL.PARTICIPANTSEQ
