					OUT_PEPI_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'TOTAL PRIORITARIOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) < 2020 THEN 'RRPP excl. PU/CC'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) >= 2024 THEN 'RRPP' --LLS 20251112 Añadido el =
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
