						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					P1.PERIODO_FORMATO AS PERIODO_FORMATO,
					OUT_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'CIERRE' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_PEPI_RESUMEN_REP.PERIODSEQ,
					NULL AS SOLO_DIFERENCIAS

				FROM EXT.OUT_PEPI_RESUMEN_REP
				INNER JOIN CTE_JER J ON J.PERIODSEQ = OUT_PEPI_RESUMEN_REP.PERIODSEQ
