				WITH CTE_JER AS
					(SELECT DISTINCT PERIODSEQ, PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODO, POS_CALLIDUS
					FROM EXT.OUT_JERARQUIA_REP
