					TO_INT(OUT_LC_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_LC_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_LC_PEPI_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_LC_PEPI_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_LC_PEPI_RESUMEN_REP.COD_REGIONAL || '-' || OUT_LC_PEPI_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_LC_PEPI_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_LC_PEPI_RESUMEN_REP.COD_OFICINA || '-' ||OUT_LC_PEPI_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_LC_PEPI_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					OUT_LC_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO AS IMPORTE_ACUMULADO,
					OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'TOTAL PRIORITARIOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) < 2020 THEN 'RRPP excl. PU/CC'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2019 < RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) AND RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2024 < RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) THEN 'RRPP'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_LC_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(OUT_LC_PEPI_RESUMEN_REP.IMPORTE,0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(OUT_LC_PEPI_RESUMEN_REP.IMPORTE,0) END AS IMPORTE_ANUAL,
				 	OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA AS V_MEDIDA,
					OUT_LC_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_LC_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					P1.PERIODO_FORMATO AS PERIODO_FORMATO,
					OUT_LC_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_LC_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'LC' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ,
					CASE WHEN (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE) )THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_LC_PEPI_RESUMEN_REP
				INNER JOIN CTE_JER J ON J.PERIODSEQ = OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_LC_PEPI_RESUMEN_REP'
				LEFT JOIN :TBL_PER_FORMAT P1 ON P1.PERIODO = OUT_LC_PEPI_RESUMEN_REP.PERIODO
				LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
           			WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
           			GROUP BY X.PAYEESEQ, X.POSITIONSEQ) B
				ON B.PAYEESEQ = OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ
    			AND B.POSITIONSEQ = OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPI_RESUMEN_FINAL_REP. LC. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Percepciones S5 Resumen', i_log_count, i_id_proceso, 'info');*/
            
            --Revisamos si se debe detener el proceso
            	CALL EXT.LIB_CREAR_TABLAS:w_stop(:v_stop);
                IF v_stop = 0 THEN
                    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!' , i_log_count, i_id_proceso, 'warning');    	
                    RETURN;
                END IF;
            END IF; 
        --FIN informe S5 PERCEPCIONES RESUMEN

		--------------------------------------------------------------------------------------------------------------------------------------
		--BRG 20251031: TABLAS PARA INFORME RAPPEL PRODUCCIÓN PROPIA AGENTES CON GRUPO
		IF :i_lista_informes = 'RPP' OR :i_lista_informes LIKE '%|RPP|%' OR :i_lista_informes LIKE '%|RPP' OR :i_lista_informes LIKE 'RPP|%' OR :i_lista_informes = 'ALL' THEN
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Creación Tablas Intermedias Informe Rappel Producción Propia.', i_log_count, i_id_proceso, 'info');
			
			IF v_periodo_posteado = 0 THEN
				--BRG 20251031: Tabla INYC_RPP_RESUMEN pasa a ser OUT_RPP_RESUMEN_REP
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_RPP_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_RESUMEN_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
				INSERT INTO EXT.OUT_RPP_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, M_GN1, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF)
					SELECT 
						PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
						PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,  
						M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,M.GENERICNUMBER1 AS M_GN1,
						PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
						PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
					FROM :TBL_AGENTES_PRIN_MES PAD_INS
					INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
						AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
						AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
					INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
						AND REG.COD_INFORME = 32.1
						AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
					INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						AND AG.COD_INFORME = 32
						AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
					--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
					;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_RESUMEN_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
				CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_RPP_RESUMEN_REP');
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');


				--BRG 20251031: Tabla INYC_RPP_DETALLE pasa a ser OUT_RPP_DETALLE_REP
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_RPP_DETALLE_REP WHERE PERIODSEQ = :i_PeriodSeq;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_DETALLE_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
				INSERT INTO EXT.OUT_RPP_DETALLE_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, NAME, VALUE, C_GN1, ST_GA1, PRODUCTID, ACCOUNTINGDATE, ST_GN1, ST_GN2, ST_GN3, ST_GD3, EVENTO, TIPO_CREDITO, PRODUCTO, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, SALESTRANSACTIONSEQ, NIF)
					SELECT
						PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
						PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
						PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
						C.NAME,C.VALUE,C.GENERICNUMBER4,
						ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE,ST.GENERICDATE2, 
						ST.EVENTO,
						CT.DESCRIPTION AS TIPO_CREDITO,
						ST.PRODUCTO,
						PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
						CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR(127)),PAD_INS.NIF
					FROM :TBL_AGENTES_PRIN_MES PAD_INS
					INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ 
						AND PAD_INS.PERIODSEQ = M.PERIODSEQ
						AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
					INNER JOIN TCMP.CS_PMCREDITTRACE PM ON M.MEASUREMENTSEQ = PM.MEASUREMENTSEQ
					INNER JOIN :TBL_CREDITOS_MES C ON PM.CREDITSEQ = C.CREDITSEQ
						AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
					INNER JOIN :TBL_TXN_MES ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
					INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
						AND REG.COD_INFORME = 32.2
						AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
					LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
						AND CT.REMOVEDATE = :v_eot
						AND CT.TENANTID = :v_idtenant
					INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						AND AG.COD_INFORME = 32
						AND AG.F_INICIO <= PAD_INS.STARTDATE AND AG.F_FIN > PAD_INS.STARTDATE
					--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
					;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_DETALLE_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
				CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_RPP_DETALLE_REP');
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
			--ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
			ELSE
				--ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
				IF v_periodo_finalizado = 0 THEN
					--BRG 20251031: Tabla INYC_LC_RPP_RESUMEN pasa a ser OUT_LC_RPP_RESUMEN_REP
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_LC_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
					DELETE FROM EXT.OUT_LC_RPP_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_LC_RPP_RESUMEN_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_RPP_RESUMEN_REP. Creditos.', i_log_count, i_id_proceso, 'debug');
					INSERT INTO EXT.OUT_LC_RPP_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, M_GN1, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF)
						SELECT 
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,  
							M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,M.GENERICNUMBER1 AS M_GN1,
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
							PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
							AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
						INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
							AND REG.COD_INFORME = 32.1
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
							AND AG.COD_INFORME = 32
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
						--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
						;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_LC_RPP_RESUMEN_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_LC_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
					CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_LC_RPP_RESUMEN_REP');
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_LC_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
			

					--BRG 20251031: Tabla INYC_LC_RPP_DETALLE pasa a ser OUT_LC_RPP_DETALLE_REP
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_LC_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
					DELETE FROM EXT.OUT_LC_RPP_DETALLE_REP WHERE PERIODSEQ = :i_PeriodSeq;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_LC_RPP_DETALLE_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
	
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_RPP_DETALLE_REP. Creditos.', i_log_count, i_id_proceso, 'debug');
						INSERT INTO EXT.OUT_LC_RPP_DETALLE_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, NAME, VALUE, C_GN1, ST_GA1, PRODUCTID, ACCOUNTINGDATE, ST_GN1, ST_GN2, ST_GN3, ST_GD3, EVENTO, TIPO_CREDITO, PRODUCTO, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, SALESTRANSACTIONSEQ, NIF)
							SELECT
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
							C.NAME,C.VALUE,C.GENERICNUMBER4,
							ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE,ST.GENERICDATE2, 
							ST.EVENTO,
							CT.DESCRIPTION AS TIPO_CREDITO,
							ST.PRODUCTO,
							PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
							CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR(127)),PAD_INS.NIF
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ 
							AND PAD_INS.PERIODSEQ = M.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
						INNER JOIN TCMP.CS_PMCREDITTRACE PM ON M.MEASUREMENTSEQ = PM.MEASUREMENTSEQ
						INNER JOIN :TBL_CREDITOS_MES C ON PM.CREDITSEQ = C.CREDITSEQ
							AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
						INNER JOIN :TBL_TXN_MES ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
						INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
							AND REG.COD_INFORME = 32.2
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
						LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
							AND CT.REMOVEDATE = :v_eot
							AND CT.TENANTID = :v_idtenant
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
							AND AG.COD_INFORME = 32
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
						--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
						;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_LC_RPP_DETALLE_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_LC_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
					CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_LC_RPP_DETALLE_REP');
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_LC_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
				--ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
				ELSE
					--BRG 20251031: Tabla INYC_BAL_RPP_RESUMEN pasa a ser OUT_BAL_RPP_RESUMEN_REP
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_BAL_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
					DELETE FROM EXT.OUT_BAL_RPP_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_BAL_RPP_RESUMEN_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_BAL_RPP_RESUMEN_REP. Creditos.', i_log_count, i_id_proceso, 'debug');
					INSERT INTO EXT.OUT_BAL_RPP_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, M_GN1, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF)
						SELECT 
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,  
							M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,M.GENERICNUMBER1 AS M_GN1,
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
							PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
							AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
						INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
							AND REG.COD_INFORME = 32.1
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
							AND AG.COD_INFORME = 32
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
						--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
						;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_BAL_RPP_RESUMEN_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_BAL_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
					CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_BAL_RPP_RESUMEN_REP');
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_BAL_RPP_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
			

					--BRG 20251031: Tabla INYC_BAL_RPP_DETALLE pasa a ser OUT_BAL_RPP_DETALLE_REP
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_BAL_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
					DELETE FROM EXT.OUT_BAL_RPP_DETALLE_REP WHERE PERIODSEQ = :i_PeriodSeq;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_BAL_RPP_DETALLE_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
	
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_BAL_RPP_DETALLE_REP. Creditos.', i_log_count, i_id_proceso, 'debug');
						INSERT INTO EXT.OUT_BAL_RPP_DETALLE_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, NAME, VALUE, C_GN1, ST_GA1, PRODUCTID, ACCOUNTINGDATE, ST_GN1, ST_GN2, ST_GN3, ST_GD3, EVENTO, TIPO_CREDITO, PRODUCTO, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, SALESTRANSACTIONSEQ, NIF)
							SELECT
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
							C.NAME,C.VALUE,C.GENERICNUMBER4,
							ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE,ST.GENERICDATE2, 
							ST.EVENTO,
							CT.DESCRIPTION AS TIPO_CREDITO,
							ST.PRODUCTO,
							PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
							CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR(127)),PAD_INS.NIF
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ 
							AND PAD_INS.PERIODSEQ = M.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
						INNER JOIN TCMP.CS_PMCREDITTRACE PM ON M.MEASUREMENTSEQ = PM.MEASUREMENTSEQ
						INNER JOIN :TBL_CREDITOS_MES C ON PM.CREDITSEQ = C.CREDITSEQ
							AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
						INNER JOIN :TBL_TXN_MES ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
						INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
							AND REG.COD_INFORME = 32.2
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
						LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
							AND CT.REMOVEDATE = :v_eot
							AND CT.TENANTID = :v_idtenant
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
							AND AG.COD_INFORME = 32
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
						--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
						;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_BAL_RPP_DETALLE_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_BAL_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
					CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_BAL_RPP_DETALLE_REP');
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_BAL_RPP_DETALLE_REP.', i_log_count, i_id_proceso, 'debug');
				
				END IF;
			END IF;
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Tablas Intermedias Informe Rappel Producción Propia', i_log_count, i_id_proceso, 'info');


			--BRG 20251113 Este código ahora se ejecuta en el RELLENAR_TABLAS
            /*-- BRG 20251031: Nueva tabla OUT_RPP_RESUMEN_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPP_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGENTE, POL_CORR, PRIMAS, PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION)
                (SELECT
                    'CIERRE' AS TIPO_INFORME,
                    RPP_RESUMEN.PERIODSEQ AS PERIODSEQ,
                    RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_RESUMEN.PERIODO,
                    SUBSTR_AFTER(RPP_RESUMEN.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
                    NULL AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_RPP_RESUMEN_REP RPP_RESUMEN
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
                    AND F.TABLA = 'OUT_RPP_RESUMEN_REP'
                WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
                F.ULTIMA_ACTUALIZACION

                UNION ALL

                SELECT
                    'BALANCE',
                    RPP_RESUMEN.PERIODSEQ,
                    RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_RESUMEN.PERIODO,
                    SUBSTR_AFTER(RPP_RESUMEN.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
                    CASE WHEN B.BALANCESEQ IS NOT NULL 
                        THEN 'SI' 
                        ELSE NULL 
                    END AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_BAL_RPP_RESUMEN_REP RPP_RESUMEN
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
                    AND F.TABLA = 'OUT_BAL_RPP_RESUMEN_REP'
                LEFT JOIN (
                    SELECT X.PAYEESEQ,
                        X.POSITIONSEQ,
                        X.PERIODSEQ,
                        MAX(X.BALANCESEQ) AS BALANCESEQ 
                    FROM TCMP.CS_BALANCE X
                    GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
                    ) B ON B.PAYEESEQ = RPP_RESUMEN.PARTICIPANTSEQ
                    AND B.POSITIONSEQ = RPP_RESUMEN.POSITIONSEQ_PRIN
                    AND B.PERIODSEQ = RPP_RESUMEN.PERIODSEQ
                WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE,
                B.BALANCESEQ, F.ULTIMA_ACTUALIZACION

                UNION ALL

                SELECT
                    'LC',
                    RPP_RESUMEN.PERIODSEQ AS PERIODSEQ,
                    RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_RESUMEN.PERIODO,
                    SUBSTR_AFTER(RPP_RESUMEN.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_RESUMEN.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
                    CASE WHEN (P.POSTPIPELINERUNDATE IS NULL OR P.POSTPIPELINERUNDATE > LAST_DAY(RPP_RESUMEN.STARTDATE)) 
                        THEN 'SI' 
                        ELSE NULL 
                    END AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_LC_RPP_RESUMEN_REP RPP_RESUMEN
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
                    AND F.TABLA = 'OUT_LC_RPP_RESUMEN_REP'
                LEFT JOIN (
                    SELECT X.PAYEESEQ,
                        X.POSITIONSEQ,
                        X.PERIODSEQ,
                        MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
                        FROM TCMP.CS_PAYMENT X
                        GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
                    ) P ON P.PAYEESEQ = RPP_RESUMEN.PARTICIPANTSEQ
                    AND P.POSITIONSEQ = RPP_RESUMEN.POSITIONSEQ_PRIN
                    AND P.PERIODSEQ = RPP_RESUMEN.PERIODSEQ
                WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
                P.POSTPIPELINERUNDATE, RPP_RESUMEN.STARTDATE, F.ULTIMA_ACTUALIZACION);
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


            -- BRG 20251031: Nueva tabla OUT_RPP_DETALLE_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPP_DETALLE_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_DETALLE_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_DETALLE_FINAL_REP(TIPO_INFORME,PERIODSEQ,POSITIONSEQ,PERIODO,PERIODO_FORMATO,COD_AGENTE,NOMBRE_AGENTE,NIF,TIPO_AGE,COD_PROD,CODIGO_POLIZA,NOMBRE_PRODUCTO,TIPO_RECIBO,FECHA_EMISION,FECHA_COBRO,POLIZAS_FIS,POLIZAS_CORR,PRIMAS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION)
                (SELECT
                    'CIERRE' AS TIPO_INFORME,
                    RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
                    RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_DETALLE.PERIODO,
                    SUBSTR_AFTER(RPP_DETALLE.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    RIGHT(PRODUCTID, 5) AS COD_PROD,
                    ST_GA1 AS CODIGO_POLIZA,
                    PRODUCTO AS NOMBRE_PRODUCTO,
                    EVENTO AS TIPO_RECIBO,
                    TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
                    TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
                    SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
                    NULL AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_RPP_DETALLE_REP RPP_DETALLE
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
                    AND F.TABLA = 'OUT_RPP_DETALLE_REP'
                WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
                PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
                F.ULTIMA_ACTUALIZACION

                UNION ALL

                SELECT
                    'BALANCE' AS TIPO_INFORME,
                    RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
                    RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_DETALLE.PERIODO,
                    SUBSTR_AFTER(RPP_DETALLE.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    RIGHT(PRODUCTID, 5) AS COD_PROD,
                    ST_GA1 AS CODIGO_POLIZA,
                    PRODUCTO AS NOMBRE_PRODUCTO,
                    EVENTO AS TIPO_RECIBO,
                    TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
                    TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
                    SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
                    CASE WHEN B.BALANCESEQ IS NOT NULL 
                        THEN 'SI' 
                        ELSE NULL 
                    END AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_BAL_RPP_DETALLE_REP RPP_DETALLE
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
                    AND F.TABLA = 'OUT_BAL_RPP_DETALLE_REP'
                LEFT JOIN (
                    SELECT X.PAYEESEQ,
                        X.POSITIONSEQ,
                        X.PERIODSEQ,
                        MAX(X.BALANCESEQ) AS BALANCESEQ 
                    FROM TCMP.CS_BALANCE X
                    GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
                    ) B ON B.PAYEESEQ = RPP_DETALLE.PARTICIPANTSEQ
                    AND B.POSITIONSEQ = RPP_DETALLE.POSITIONSEQ_PRIN
                    AND B.PERIODSEQ = RPP_DETALLE.PERIODSEQ
                WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
                PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
                B.BALANCESEQ, F.ULTIMA_ACTUALIZACION

                UNION ALL

                SELECT
                    'LC' AS TIPO_INFORME,
                    RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
                    RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
                    RPP_DETALLE.PERIODO,
                    SUBSTR_AFTER(RPP_DETALLE.PERIODO, ' ') || CASE WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Enero' THEN ' 01 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Febrero' THEN ' 02 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Marzo' THEN ' 03 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Abril' THEN ' 04 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Mayo' THEN ' 05 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Junio' THEN ' 06 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Julio' THEN ' 07 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Agosto' THEN ' 08 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Octubre' THEN ' 10 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
                            WHEN SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
                            END
                        || SUBSTR_BEFORE(RPP_DETALLE.PERIODO, ' ') AS PERIODO_FORMATO,
                    POS_PRIN AS COD_AGENTE,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
                    RIGHT(PRODUCTID, 5) AS COD_PROD,
                    ST_GA1 AS CODIGO_POLIZA,
                    PRODUCTO AS NOMBRE_PRODUCTO,
                    EVENTO AS TIPO_RECIBO,
                    TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
                    TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
                    SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
                    CASE 
                        WHEN (P.POSTPIPELINERUNDATE IS NULL 
                        OR P.POSTPIPELINERUNDATE > LAST_DAY(
                            (SELECT STARTDATE 
                            FROM CS_PERIOD 
                            WHERE PERIODSEQ = RPP_DETALLE.PERIODSEQ 
                                AND REMOVEDATE = TO_DATE('22000101')
                    )))
                        THEN 'SI' 
                        ELSE NULL 
                    END AS SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
                FROM EXT.OUT_BAL_RPP_DETALLE_REP RPP_DETALLE
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
                    AND F.TABLA = 'OUT_LC_RPP_DETALLE_REP'
                LEFT JOIN (
                    SELECT X.PAYEESEQ,
                        X.POSITIONSEQ,
                        X.PERIODSEQ,
                        MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
                        FROM TCMP.CS_PAYMENT X
                        GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
                    ) P ON P.PAYEESEQ = RPP_DETALLE.PARTICIPANTSEQ
                    AND P.POSITIONSEQ = RPP_DETALLE.POSITIONSEQ_PRIN
                    AND P.PERIODSEQ = RPP_DETALLE.PERIODSEQ
                WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
                GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
                POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
                PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
                P.POSTPIPELINERUNDATE, F.ULTIMA_ACTUALIZACION);
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_DETALLE_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');*/

            --Revisamos si se debe detener el proceso
			CALL EXT.LIB_CREAR_TABLAS:w_stop(:v_stop);
			IF v_stop = 0 THEN
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!' , i_log_count, i_id_proceso, 'warning');    	
				RETURN;
			END IF;

		END IF;
		--FIN informe Rappel Producción Propia

		--BRG 20251113 Este código ahora se ejecuta en el RELLENAR_TABLAS
		/*---------------------------------------------------------------------------------------------------------------------------------------
		--LLS 20251031 Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
        --Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- todos los meses
		IF (:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%|RPA|%' OR :i_lista_informes LIKE '%|RPA' OR :i_lista_informes LIKE 'RPA|%' OR :i_lista_informes = 'ALL' )
			--AND SUBSTR_BEFORE(:v_period_name, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') --LLS 20251112: comentado
			THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN (Mensual)', i_log_count, i_id_proceso, 'info'); --LLS 20251112: añadido texto mensual

			--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'No es fin de trimestre.', i_log_count, i_id_proceso, 'debug');--LLS 20251112: comentado
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual)', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). CIERRE', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual

			INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
				SELECT DISTINCT 'OCASO' COMPANYA
					, TIPO_PAGO
					, ORIGEN
					, RPA.PERIODSEQ
					, STARTDATE 
					, PERIODO_ORIGINAL
					, RPA.PERIODO PERIODO_CAMPO
					, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
										CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
											END
										|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
					, QUARTER
					, POSITIONSEQ
					, N_MEDIDA
					, CASE	--tabla Tabla_Resumen_Total
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
							--tabla Tabla_Resumen_Productos
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							ELSE NULL
						END COMISION_RESUMEN
					, CASE	--tabla Tabla_Objetivos
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
							ELSE NULL
						END COMISION_OBJ
					, CASE	--tabla Tabla_Pago_Mensual
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251112: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251112: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							ELSE NULL
						END COMISION_PAGO
					, CASE	--tabla Tabla_Trim_por_mes
						WHEN (RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
							AND ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45)
						THEN CASE
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN (YEAR < 2022 AND N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes') 
									OR (YEAR >= 2022 AND N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' ) THEN 'Pólizas T.R.' --LLS 20251110: Corregido
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' AND YEAR >= 2022 THEN 'Pólizas Ocaso Oro' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							--dato Cumple Objetivos Reg. Trim.
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND YEAR >= 2022 THEN 'Cumple Objetivos Reg. Trim.' --LLS 20251110: Añadida la condición de año
							--tabla 
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' AND YEAR >= 2022 THEN 'Escalado Reg. Trim.' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' AND YEAR >= 2022 THEN 'Total Abono Reg. Trim.' --LLS 20251110: Añadida la condición de año

							ELSE NULL END
						ELSE NULL
						END COMISION_REG
					, ROUND(V_MEDIDA, 2) V_MEDIDA
					, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
					, POS_PRIN
					, NOMBRE
					, POS_CALLIDUS
					, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
					, POSITIONNAME
					, M_GN1
					, TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE AS TIPO_AGENTE
					, ID_TIPO_AGENTE
					, NIF
					, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
					, FEC_ACTUALIZACION
					, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

				FROM (	SELECT DISTINCT 'CIERRE' TIPO_PAGO
							,  'Cierre' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, INYC_RPA_RESUMEN.PERIODO
							, INYC_RPA_RESUMEN.YEAR --LLS 20251110: Incluido
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(INYC_RPA_RESUMEN.STARTDATE, 1) 
								THEN LAST_DAY(INYC_RPA_RESUMEN.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END FEC_ACTUALIZACION
						
						FROM EXT.OUT_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						
						INNER JOIN (SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F 
							ON F.PERIODO = INYC_RPA_RESUMEN.PERIODO
								AND F.TABLA = 'OUT_RPA_RESUMEN_REP'
						
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq

						) RPA;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual

			--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info'); --LLS 20251112: comentado

        		
			--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- si fin de trimestre
			IF /*(:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%|RPA|%' OR :i_lista_informes LIKE '%|RPA' OR :i_lista_informes LIKE 'RPA|%' OR :i_lista_informes = 'ALL' )
				AND --LLS 20251110: comentado
			IF	SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
				AND SUBSTR_AFTER(:v_period_name, ' ') >= 2022 --LLS 20251110: Añadido
				THEN
				
				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info'); --LLS 20251112: comentado
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN (Trimestre)', i_log_count, i_id_proceso, 'info'); --LLS 20251112: añadido texto Trimestre

				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Sí es fin de trimestre.', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: comentado
				
				--Borrado del periodo en los datos de cierre --LLS 20251112: comentado
				/*CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq ' || i_PeriodSeq, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Cierre';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				--Borrado del periodo-1 en los datos de balance
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-1 ' || v_PeriodSeq_1, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_1 AND ORIGEN = 'Balance';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas PeriodSeq-1: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido PeriodSeq-1
				
				--Borrado del periodo-2 en los datos de balance
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-2 ' || v_PeriodSeq_2, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_2 AND ORIGEN = 'Balance';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas PeriodSeq-2: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido PeriodSeq-1


				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Trimestre). CIERRE', i_log_count, i_id_proceso, 'debug');--LLS 20251112: añadido texto Trimestre

				INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
					SELECT DISTINCT 'OCASO' COMPANYA
						, TIPO_PAGO
						, ORIGEN
						, RPA.PERIODSEQ
						, STARTDATE 
						, PERIODO_ORIGINAL
						, RPA.PERIODO PERIODO_CAMPO
						, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
											CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
												END
											|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
						, QUARTER
						, POSITIONSEQ
						, N_MEDIDA
						, CASE	--tabla Tabla_Resumen_Total
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
								--tabla Tabla_Resumen_Productos
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								ELSE NULL
							END COMISION_RESUMEN
						, CASE	--tabla Tabla_Objetivos
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
								ELSE NULL
							END COMISION_OBJ
						, CASE	--tabla Tabla_Pago_Mensual
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
								ELSE NULL
							END COMISION_PAGO
						, CASE	--tabla Tabla_Trim_por_mes
							WHEN (RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
								AND ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45)
							THEN CASE
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
								WHEN (YEAR < 2022 AND N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes') 
										OR (YEAR >= 2022 AND N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' ) THEN 'Pólizas T.R.' --LLS 20251112: Corregido
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' AND YEAR >= 2022 THEN 'Pólizas Ocaso Oro' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251112: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251112: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251112: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251112: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251112: Añadida la condición de año
								--dato Cumple Objetivos Reg. Trim.
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND YEAR >= 2022 THEN 'Cumple Objetivos Reg. Trim.' --LLS 20251112: Añadida la condición de año
								--tabla 
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' AND YEAR >= 2022 THEN 'Escalado Reg. Trim.' --LLS 20251112: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' AND YEAR >= 2022 THEN 'Total Abono Reg. Trim.' --LLS 20251112: Añadida la condición de año

								ELSE NULL END
							ELSE NULL
							END COMISION_REG
						, ROUND(V_MEDIDA, 2) AS V_MEDIDA
						, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
						, POS_PRIN
						, NOMBRE
						, POS_CALLIDUS
						, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
						, POSITIONNAME
						, M_GN1
						, TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE AS TIPO_AGENTE
						, ID_TIPO_AGENTE
						, NIF
						, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
						, FEC_ACTUALIZACION
						, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

					FROM (	/*--LLS 20251112: comentado
							SELECT DISTINCT 'CIERRE' TIPO_PAGO
								,  'Cierre' ORIGEN
								, INYC_RPA_RESUMEN.PERIODSEQ
								, INYC_RPA_RESUMEN.STARTDATE 
								, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
								, INYC_RPA_RESUMEN.PERIODO
								, INYC_RPA_RESUMEN.QUARTER
								, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
								, INYC_RPA_RESUMEN.N_MEDIDA
								, INYC_RPA_RESUMEN.V_MEDIDA
								, INYC_RPA_RESUMEN.POS_PRIN
								, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
								, J.POS_CALLIDUS
								, INYC_RPA_RESUMEN.POSITIONNAME
								, INYC_RPA_RESUMEN.M_GN1
								, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
								, INYC_RPA_RESUMEN.TIPO_AGENTE
								, INYC_RPA_RESUMEN.NIF
								, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(INYC_RPA_RESUMEN.STARTDATE, 1) 
									THEN LAST_DAY(INYC_RPA_RESUMEN.STARTDATE)
									ELSE F.ULTIMA_ACTUALIZACION
									END FEC_ACTUALIZACION
							
							FROM EXT.OUT_RPA_RESUMEN_REP INYC_RPA_RESUMEN
							
							INNER JOIN (SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
										FROM EXT.OUT_JERARQUIA_REP) J
								ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
									AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
							
							LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F 
								ON F.PERIODO = INYC_RPA_RESUMEN.PERIODO
									AND F.TABLA = 'OUT_RPA_RESUMEN_REP'
							
							WHERE 1 = 1
								AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
								AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq

							UNION ALL
							
							SELECT DISTINCT  'CIERRE' TIPO_PAGO
								,  'Balance' ORIGEN
								, INYC_RPA_RESUMEN.PERIODSEQ
								, INYC_RPA_RESUMEN.STARTDATE 
								, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
								, CASE WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Febrero'
										THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Mayo'
										THEN 'Junio ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Agosto'
										THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Noviembre'
										THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									END PERIODO
								, INYC_RPA_RESUMEN.YEAR --LLS 20251110: Incluido
								, INYC_RPA_RESUMEN.QUARTER
								, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
								, INYC_RPA_RESUMEN.N_MEDIDA
								, INYC_RPA_RESUMEN.V_MEDIDA
								, INYC_RPA_RESUMEN.POS_PRIN
								, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
								, J.POS_CALLIDUS
								, INYC_RPA_RESUMEN.POSITIONNAME
								, INYC_RPA_RESUMEN.M_GN1
								, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
								, INYC_RPA_RESUMEN.TIPO_AGENTE
								, INYC_RPA_RESUMEN.NIF
								, NULL FEC_ACTUALIZACION
							FROM EXT.OUT_BAL_RPA_RESUMEN_REP INYC_RPA_RESUMEN
							INNER JOIN (SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
										FROM EXT.OUT_JERARQUIA_REP) J
								ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
									AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
							WHERE 1 = 1
								AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
								AND INYC_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,43,44,45,49)
								AND SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
								AND INYC_RPA_RESUMEN.PERIODSEQ IN (:v_PeriodSeq_1, :v_PeriodSeq_2)

							) RPA;
				v_num_rows := ::ROWCOUNT;

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Trimestre). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');--LLS 20251112: añadido texto Trimestre

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info');
			
			END IF;
		END IF;
        --FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)*/
        --*/*/*/
		

		--------------------------------------------------------------------------------------------------------------------------------------
		--BRG 20251031: TABLAS PARA INFORME Rappel Producción Inspectores
		IF :i_lista_informes = 'RPI' OR :i_lista_informes LIKE '%|RPI|%' OR :i_lista_informes LIKE '%|RPI' OR :i_lista_informes LIKE 'RPI|%' OR :i_lista_informes = 'ALL' THEN
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Creación Tablas Intermedias Informe Rappel Producción Inspectores.', i_log_count, i_id_proceso, 'info');

			IF v_periodo_posteado = 0 THEN
				--BRG 20251031: Tabla INYC_RPI_RESUMEN pasa a ser OUT_RPI_RESUMEN_REP
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPI_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_RPI_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPI_RESUMEN_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPI_RESUMEN_REP. Medidas.', i_log_count, i_id_proceso, 'debug');
				INSERT INTO EXT.OUT_RPI_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, N_CREDITO, V_CREDITO, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF, NIVEL_PTO_VENTA, COD_PTO_VENTA, PTO_VENTA, NIVEL_OFICINA, COD_OFICINA, OFICINA, NIVEL_SUCURSAL, COD_SUCURSAL, SUCURSAL, NIVEL_REGIONAL, COD_REGIONAL, REGIONAL, C_GN4)
					SELECT
						PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
						PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
						M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
						PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
						C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
						PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
						--ALM 20180126: Anadimos un * al codigo del agente para informar si el agente pertenece al grupo del inspector
						CASE WHEN PAD_AG.MANAGERPARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ THEN '*' ELSE '' END || PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
						PAD_INS.POS_PRIN,
						PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
						--ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
						,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																		ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
							WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
																ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
							ELSE 4
						END AS NIVEL_PTO_VENTA,
						PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
						PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
						CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																			ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																					ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																			ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																			ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
							ELSE 3
						END AS NIVEL_OFICINA,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
							ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
							ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
						CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																						ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							ELSE 2
						END AS NIVEL_SUCURSAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
								ELSE PAD_PTO_VENTA.POSITIONNAME END 
						END AS COD_SUCURSAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
								ELSE PAD_PTO_VENTA.LASTNAME END 
						END AS SUCURSAL,
						1 AS NIVEL_REGIONAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
									ELSE PAD_PTO_VENTA.POSITIONNAME END
						END END AS COD_REGIONAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
									ELSE PAD_PTO_VENTA.LASTNAME END
						END END AS REGIONAL,
						C.GENERICNUMBER4 as C_GN4
					FROM :TBL_AGENTES_PRIN_MES PAD_INS
					INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
						AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
						AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
					INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
						AND REG.COD_INFORME in (1.1, 25.1)
						AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
					LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
						AND PMCT.TENANTID = :v_idtenant 
					LEFT OUTER JOIN :TBL_CREDITOS_MES C ON PMCT.CREDITSEQ=C.CREDITSEQ
					LEFT OUTER JOIN :TBL_TXN_MES ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
					LEFT OUTER JOIN :TBL_AGENTES_MES PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
						AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
						AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
						AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
						AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
						AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
					INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						AND AG.COD_INFORME in (1, 25.1)
						AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
					--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
					;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPI_RESUMEN_REP. Medidas. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				           					
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPI_RESUMEN_REP. Incentivos.', i_log_count, i_id_proceso, 'debug');
				INSERT INTO EXT.OUT_RPI_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, N_CREDITO, V_CREDITO, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF, NIVEL_PTO_VENTA, COD_PTO_VENTA, PTO_VENTA, NIVEL_OFICINA, COD_OFICINA, OFICINA, NIVEL_SUCURSAL, COD_SUCURSAL, SUCURSAL, NIVEL_REGIONAL, COD_REGIONAL, REGIONAL, C_GN4)
					SELECT
						PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
						PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
						I.NAME AS N_MEDIDA,I.VALUE AS V_MEDIDA, 
						PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
						'' AS N_CREDITO,0 AS V_CREDITO,
						'' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
						'' AS POSITIONNAME_AG,
						PAD_INS.POS_PRIN,
						PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
						--ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
						,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																		ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
							WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
																ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
							ELSE 4
						END AS NIVEL_PTO_VENTA,
						PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
						PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
						CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																			ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																					ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																			ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																			ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
							ELSE 3
						END AS NIVEL_OFICINA,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
							ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
							ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
						CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
									ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																						ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
							ELSE 2
						END AS NIVEL_SUCURSAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
								ELSE PAD_PTO_VENTA.POSITIONNAME END 
						END AS COD_SUCURSAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
								ELSE PAD_PTO_VENTA.LASTNAME END 
						END AS SUCURSAL,
						1 AS NIVEL_REGIONAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
									ELSE PAD_PTO_VENTA.POSITIONNAME END
						END END AS COD_REGIONAL,
						CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
							ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
									ELSE PAD_PTO_VENTA.LASTNAME END
						END END AS REGIONAL,
						--ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
						0 as C_GN4
					FROM :TBL_AGENTES_PRIN_MES PAD_INS
					INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
						AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
						AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
					INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
					INNER JOIN EXT.CONF_REGLAS_REP REG ON I.NAME = REG.REGLA
						AND REG.COD_INFORME in (1.1, 25.1)
						AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
						AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
						AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
						AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
					LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
						AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
					INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						AND AG.COD_INFORME in (1, 25.1)
						AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
					--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
					;
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPI_RESUMEN_REP. Incentivos. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPI_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
				CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'OUT_RPI_RESUMEN_REP');
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de OUT_RPI_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
			--ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
			ELSE
				--ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
				IF v_periodo_finalizado = 0 THEN
					--BRG 20251031: Tabla INYC_LC_RPI_RESUMEN pasa a ser OUT_LC_RPI_RESUMEN_REP
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_LC_RPI_RESUMEN_REP.', i_log_count, i_id_proceso, 'debug');
					DELETE FROM EXT.OUT_LC_RPI_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_LC_RPI_RESUMEN_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_RPI_RESUMEN_REP. Medidas.', i_log_count, i_id_proceso, 'debug');
					INSERT INTO EXT.OUT_LC_RPI_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, N_CREDITO, V_CREDITO, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF, NIVEL_PTO_VENTA, COD_PTO_VENTA, PTO_VENTA, NIVEL_OFICINA, COD_OFICINA, OFICINA, NIVEL_SUCURSAL, COD_SUCURSAL, SUCURSAL, NIVEL_REGIONAL, COD_REGIONAL, REGIONAL, C_GN4)
						SELECT
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
							M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
							C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
							PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
							--ALM 20180126: Anadimos un * al codigo del agente para informar si el agente pertenece al grupo del inspector
							CASE WHEN PAD_AG.MANAGERPARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ THEN '*' ELSE '' END || PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
							PAD_INS.POS_PRIN,
							PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
							--ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
							,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																		ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																			ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																	ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
								WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
																	ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
								ELSE 4
							END AS NIVEL_PTO_VENTA,
							PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
							PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
							CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																						ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																				ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
								ELSE 3
							END AS NIVEL_OFICINA,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
								ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
								ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
							CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
										ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																						ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																							ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								ELSE 2
							END AS NIVEL_SUCURSAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
									ELSE PAD_PTO_VENTA.POSITIONNAME END 
							END AS COD_SUCURSAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
									ELSE PAD_PTO_VENTA.LASTNAME END 
							END AS SUCURSAL,
							1 AS NIVEL_REGIONAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
										ELSE PAD_PTO_VENTA.POSITIONNAME END
							END END AS COD_REGIONAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
										ELSE PAD_PTO_VENTA.LASTNAME END
							END END AS REGIONAL,
							C.GENERICNUMBER4 as C_GN4
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN :TBL_MEDIDAS_MES M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
							AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
						INNER JOIN EXT.CONF_REGLAS_REP REG ON M.NAME = REG.REGLA
							AND REG.COD_INFORME in (1.1, 25.1)
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
						LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
							AND PMCT.TENANTID = :v_idtenant 
						LEFT OUTER JOIN :TBL_CREDITOS_MES C ON PMCT.CREDITSEQ=C.CREDITSEQ
						LEFT OUTER JOIN :TBL_TXN_MES ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
						LEFT OUTER JOIN :TBL_AGENTES_MES PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
							AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
							AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
							AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
							AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
							AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
							AND AG.COD_INFORME in (1, 25.1)
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
						--WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
						;
					v_num_rows := ::ROWCOUNT;
					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_LC_RPI_RESUMEN_REP. Medidas. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_RPI_RESUMEN_REP. Incentivos.', i_log_count, i_id_proceso, 'debug');
					INSERT INTO EXT.OUT_LC_RPI_RESUMEN_REP (PARTICIPANTSEQ, POSITIONSEQ_PRIN, PERIODSEQ, PERIODO, QUARTER, YEAR, STARTDATE, N_MEDIDA, V_MEDIDA, BOUSERID, FIRSTNAME, MIDDLENAME, LASTNAME, POSITIONNAME, N_CREDITO, V_CREDITO, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE, NIF, NIVEL_PTO_VENTA, COD_PTO_VENTA, PTO_VENTA, NIVEL_OFICINA, COD_OFICINA, OFICINA, NIVEL_SUCURSAL, COD_SUCURSAL, SUCURSAL, NIVEL_REGIONAL, COD_REGIONAL, REGIONAL, C_GN4) 
						SELECT
							PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
							PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
							I.NAME AS N_MEDIDA,I.VALUE AS V_MEDIDA, 
							PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
							'' AS N_CREDITO,0 AS V_CREDITO,
							'' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
							--ALM 20180126: Anadimos un * al codigo del agente para informar si el agente pertenece al grupo del inspector
							'' AS POSITIONNAME_AG,
							PAD_INS.POS_PRIN,
							PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
							--ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
							,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																		ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																			ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																	ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																	ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
								WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
																	ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
								ELSE 4
							END AS NIVEL_PTO_VENTA,
							PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
							PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
							CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																						ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
																				ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
																				ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
								ELSE 3
							END AS NIVEL_OFICINA,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
								ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
								ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
							CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
										ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
										ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
																					ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
																						ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
																							ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
								ELSE 2
							END AS NIVEL_SUCURSAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
									ELSE PAD_PTO_VENTA.POSITIONNAME END 
							END AS COD_SUCURSAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
									ELSE PAD_PTO_VENTA.LASTNAME END 
							END AS SUCURSAL,
							1 AS NIVEL_REGIONAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
										ELSE PAD_PTO_VENTA.POSITIONNAME END
							END END AS COD_REGIONAL,
							CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
								ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
									ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
										ELSE PAD_PTO_VENTA.LASTNAME END
							END END AS REGIONAL,
							--ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
							0 as C_GN4
						FROM :TBL_AGENTES_PRIN_MES PAD_INS
						INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
							AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
							AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
						--ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
						INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
						INNER JOIN EXT.CONF_REGLAS_REP REG ON I.NAME = REG.REGLA
						--ATV 20240719 Anyadimos el informe 25.1
							AND REG.COD_INFORME in (1.1, 25.1)
							AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
						--ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
							AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
							AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
							AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
						LEFT OUTER JOIN :TBL_OFICINAS_MES PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
							AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
						INNER JOIN EXT.CONF_AGENTES_REP AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						--ATV 20240719 Anyadimos el informe 25.1
							AND AG.COD_INFORME in (1, 25.1)
							AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
