							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO PERIODO_ORIGINAL,
							CASE WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								ELSE INYC_RPI_RESUMEN.PERIODO
								END PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM  EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
